import {mountRuleBuilder} from '/studio/admin.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(p,d){const r=await fetch('/api/'+p,{method:d?'POST':'GET',headers:d?{'Content-Type':'application/json'}:{},body:d?JSON.stringify(d):undefined});const v=await r.json();if(!r.ok)throw Error(v.error);return v;}
export async function mountProducts(root,message,inventory=false){
 const data=await api('admin/products'),ruleData=await api('admin/rules');let products=data.products;
 root.innerHTML='<section data-product-list><div class="toolbar"><input data-search placeholder="Search products"><select data-stock-filter aria-label="Filter products"><option value="">All products</option><option value="active">Visible</option><option value="hidden">Hidden</option><option value="out">Out of stock</option></select><button class="primary" data-new-product>Add product</button></div><div class="panel" data-list></div></section><div data-product-editor></div>';
 const $=s=>root.querySelector(s),money=v=>new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD'}).format(v);
 function list(){const q=$('[data-search]').value.toLowerCase(),filter=$('[data-stock-filter]').value;const rows=products.filter(p=>p.name.toLowerCase().includes(q)&&(!filter||filter==='active'&&p.active||filter==='hidden'&&!p.active||filter==='out'&&p.stock===0));$('[data-list]').innerHTML=`<div class="section-heading"><h2>${inventory?'Inventory':'Products'} <span class="muted">${rows.length}</span></h2><span class="muted">Manage images, information and pricing in one place</span></div><div class="scroll"><table><thead><tr><th>Product</th><th>Visibility</th><th>Inventory</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td><div class="product-list-name">${p.images?.[0]?`<img src="${esc(p.images[0])}" alt="">`:'<span class="product-placeholder">◇</span>'}<b>${esc(p.name)}</b></div></td><td><span class="pill ${p.active?'paid':'draft'}">${p.active?'Visible':'Hidden'}</span></td><td>${p.stock===null?'In stock · unlimited':p.stock===0?'Out of stock':p.stock+' available'}</td><td><button data-edit-product="${p.id}">Edit product</button></td></tr>`).join('')}</tbody></table></div>`;}
 async function editor(p){const c=structuredClone(p||{id:'product-'+crypto.randomUUID().slice(0,8),name:'',ruleId:'',studioProductId:'',active:true,artwork:false,stock:null,description:'',images:[]});c.path||='/satin/shop/products/'+c.id;c.images||=[];c.templates||=[];let rule=structuredClone(ruleData.rules.find(r=>r.id===c.ruleId)||{id:c.id,label:'New product',path:c.path,fields:[{key:'quantity',label:'Quantity',type:'number',default:1,min:1,max:10000,step:1}],constants:{unitPrice:0},formula:'quantity * unitPrice',taxPercent:13,discount:{type:'percent',value:0},deposit:{type:'percent',value:50},revision:0});c.ruleId=rule.id;
 $('[data-product-list]').hidden=true;root.classList.add('product-editing');
 $('[data-product-editor]').innerHTML=`<form data-product-form><div class="product-editor-bar"><div><button type="button" data-close-product>← Products</button><h2>${esc(c.name||'New product')}</h2></div><div class="toolbar"><a class="button" href="${esc(c.path)}/" target="_blank" rel="noopener">View product ↗</a><button type="button" data-close-product>Cancel</button><button class="primary">Save product</button></div></div><p data-product-status role="status"></p><div class="product-editor-layout"><div class="product-editor-main"><section class="panel"><h2>Images</h2><p class="muted">The first image is your product cover. Select from your Satin photo library or upload a new image.</p><div class="product-media" data-media></div><div class="toolbar"><label class="media-upload">＋ Upload images<input data-image-upload type="file" accept="image/png,image/jpeg,image/webp" multiple></label><button type="button" data-photo-library>Choose from Satin photos</button></div><div data-library hidden class="product-photo-library"></div></section><section class="panel"><h2>Product information</h2><label>Product name<input name="name" value="${esc(c.name)}" required maxlength="120" placeholder="Enter a product name"></label><label>Description<textarea name="description" rows="6" maxlength="2000" placeholder="Describe materials, finishes and what is included">${esc(c.description)}</textarea></label><label>Details tab<textarea name="details" rows="5">${esc(c.details)}</textarea></label><label>File preparation steps · one per line<textarea name="filePrep" rows="5">${esc(c.filePrep)}</textarea></label><label>Reviews tab content<textarea name="reviews" rows="4">${esc(c.reviews)}</textarea></label><h3>Paid digital artwork file</h3><p>Upload the final vector or ZIP sold with this product. Buyers receive it only after verified payment.</p><input type="file" data-digital-upload accept=".svg,.pdf,.ai,.eps,.zip"><p data-digital-status></p><h3>Downloadable PDF templates</h3><p class="muted">Edit labels, upload replacements or remove downloads. Save product to publish.</p><div data-template-list></div><label>Upload PDF templates<input type="file" data-product-template accept="application/pdf,.pdf" multiple></label></section><section class="panel"><div class="section-heading"><h2>Pricing</h2><span class="pill">CAD</span></div><p class="muted">Edit your pricing values below. Your options and calculation stay connected to the customer estimate.</p><label>Product pricing note<textarea data-price-note rows="3">${esc(rule.priceNote)}</textarea></label><div class="form-grid" data-pricing></div><div class="product-price-preview" data-price-preview></div><details><summary>Advanced calculation</summary><p class="muted">Use quantity and your option keys in this formula.</p><label>Formula<textarea data-formula rows="3">${esc(rule.formula)}</textarea></label></details></section><section class="panel"><div class="section-heading"><div><h2>Product options & quantities</h2><p class="muted">Manage sizes, materials, choices and the full pricing form.</p></div><button type="button" data-options>Edit options</button></div><div data-options-summary></div><div data-rule-editor hidden></div></section></div><aside><section class="panel"><h2>Visibility</h2><label class="check"><input name="active" type="checkbox" ${c.active?'checked':''}>Show on website</label></section><section class="panel"><h2>Inventory</h2><label>Available quantity<input name="stock" type="number" min="0" step="1" value="${c.stock??''}" placeholder="Unlimited"></label><p class="muted">Leave blank for made-to-order products. Set 0 to stop orders.</p></section><section class="panel"><h2>Artwork & design</h2><label class="check"><input name="artwork" type="checkbox" ${c.artwork?'checked':''}>Requires artwork</label><label>Design Studio<select name="studioProductId"><option value="">No studio</option>${ruleData.products.map(p=>`<option value="${p.id}" ${p.id===c.studioProductId?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label></section><section class="panel"><h2>Page settings</h2><details><summary>Website address</summary><label>Product page<input name="path" value="${esc(c.path)}" required></label></details></section></aside></div></form>`;
 const form=$('[data-product-form]');let uploading=0;form.querySelector('[data-digital-upload]').onchange=async e=>{const file=e.target.files[0];if(!file)return;uploading++;try{const fd=new FormData();fd.set('ruleId',rule.id);fd.set('file',file);const r=await fetch('/api/admin/digital-upload',{method:'POST',body:fd}),v=await r.json();if(!r.ok)throw Error(v.error);form.querySelector('[data-digital-status]').textContent='Paid download attached: '+v.name;}catch(err){form.querySelector('[data-digital-status]').textContent=err.message;}finally{uploading--;}};
 function templateList(){$('[data-template-list]').innerHTML=c.templates.map((t,n)=>`<div class="panel"><label>Download label<input data-template-label="${n}" value="${esc(t.label)}" maxlength="120"></label><a href="${esc(t.url)}" target="_blank" rel="noopener">View PDF ↗</a> <button type="button" data-remove-template="${n}">Remove template</button></div>`).join('')||'<p class="muted">No template downloads. Upload a PDF to add one.</p>';}
 function media(){$('[data-media]').innerHTML=c.images.map((src,n)=>`<div class="product-media-item"><img src="${esc(src)}" alt="Product image ${n+1}"><span>${n===0?'Cover':'Image '+(n+1)}</span><div>${n?`<button type="button" data-cover="${n}">Make cover</button>`:''}<button type="button" data-remove-photo="${n}">Remove</button></div></div>`).join('')||'<div class="media-empty">Add your first product image</div>';}
 function pricing(){const constants=Object.entries(rule.constants).map(([k,v])=>`<label>${esc(rule.constantLabels?.[k]||(/^v[0-9]+c[0-9]+$/.test(k)?(rule.fields.find(f=>f.key==='vehicle')?.options[+k.match(/^v([0-9]+)/)[1]]?.label||'Vehicle')+' · '+['Full wrap','With roof','1/3 wrap','1/2 wrap','3/4 wrap','Channel wrap','Decals'][+k.match(/c([0-9]+)$/)[1]]:k.replace(/([A-Z])/g,' $1').replaceAll('_',' ')))}<input data-constant="${esc(k)}" type="number" step="any" value="${v}"></label>`).join('');const tiers=[...rule.formula.matchAll(/if\(quantity <= ([0-9.]+), ([0-9.]+)/g)];let tierInputs='';if(tiers.length){tiers.forEach((m,n)=>{tierInputs+=`<label>Up to ${m[1]} · price (CAD)<input data-tier="${n}" type="number" min="0" step=".01" value="${m[2]}"></label>`;});const last=rule.formula.match(/, ([0-9.]+)\)\)/);if(last)tierInputs+=`<label>Above ${tiers.at(-1)[1]} · price (CAD)<input data-last-tier type="number" min="0" step=".01" value="${last[1]}"></label>`;}
 $('[data-pricing]').innerHTML=constants+tierInputs+`<label>Tax (%)<input data-rule-tax type="number" min="0" max="30" step=".01" value="${rule.taxPercent}"></label>`;
 $('[data-options-summary]').innerHTML=rule.fields.map(f=>`<div class="product-option-row"><b>${esc(f.label)}</b><span>${esc(f.options?.map(o=>o.label).join(' · ')||f.min+' – '+f.max)}</span></div>`).join('');$('[data-formula]').value=rule.formula;preview();}
 async function preview(){try{const {calculate}=await import('/studio/model.mjs');const q=calculate(rule,Object.fromEntries(rule.fields.map(f=>[f.key,f.default])));$('[data-price-preview]').innerHTML=`<span>Estimate for default selections</span><b>${money(q.total/100)}</b><small>Includes tax · ${money(q.subtotal/100)} before tax</small>`;}catch(err){$('[data-price-preview]').textContent=err.message;}}
 form.oninput=e=>{const t=e.target;if(t.dataset.templateLabel!==undefined)c.templates[Number(t.dataset.templateLabel)].label=t.value;if(t.hasAttribute('data-price-note'))rule.priceNote=t.value;if(t.dataset.constant)rule.constants[t.dataset.constant]=Number(t.value);if(t.hasAttribute('data-rule-tax'))rule.taxPercent=Number(t.value);if(t.hasAttribute('data-formula'))rule.formula=t.value;if(t.hasAttribute('data-tier')){let n=0;rule.formula=rule.formula.replace(/if\(quantity <= ([0-9.]+), ([0-9.]+)/g,(m,q,v)=>'if(quantity <= '+q+', '+(n++===Number(t.dataset.tier)?t.value:v));$('[data-formula]').value=rule.formula;}if(t.hasAttribute('data-last-tier')){rule.formula=rule.formula.replace(/, ([0-9.]+)\)\)/,', '+t.value+'))');$('[data-formula]').value=rule.formula;}preview();};
 $('[data-image-upload]').onchange=async e=>{uploading++;try{for(const file of e.target.files){if(c.images.length>=12)throw Error('Use up to 12 images');const fd=new FormData();fd.set('file',file);const r=await fetch('/api/admin/product-image-upload',{method:'POST',body:fd}),v=await r.json();if(!r.ok)throw Error(v.error);c.images.push(v.url);media();}message('Images uploaded. Save product to publish them.');}catch(err){$('[data-product-status]').textContent=err.message;}finally{uploading--;e.target.value='';}};
 form.onclick=async e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-close-product')){root.classList.remove('product-editing');$('[data-product-editor]').innerHTML='';$('[data-product-list]').hidden=false;}if(b.dataset.removeTemplate!==undefined){c.templates.splice(Number(b.dataset.removeTemplate),1);templateList();}if(b.dataset.removePhoto!==undefined){c.images.splice(Number(b.dataset.removePhoto),1);media();}if(b.dataset.cover!==undefined){c.images.unshift(c.images.splice(Number(b.dataset.cover),1)[0]);media();}if(b.hasAttribute('data-photo-library')){const box=$('[data-library]');box.hidden=!box.hidden;if(!box.innerHTML){const {images}=await api('admin/product-images');box.innerHTML=images.map(src=>`<button type="button" data-library-image="${esc(src)}"><img loading="lazy" src="${esc(src)}" alt="${esc(src.split('/').at(-1))}"></button>`).join('');}}if(b.dataset.libraryImage){if(c.images.length<12&&!c.images.includes(b.dataset.libraryImage)){c.images.push(b.dataset.libraryImage);media();}}if(b.hasAttribute('data-options')){const box=$('[data-rule-editor]');box.hidden=!box.hidden;if(!box.hidden)await mountRuleBuilder(box,async(text,error)=>{message(text,error);if(!error&&text.includes('published')){ruleData.rules=(await api('admin/rules')).rules;rule=structuredClone(ruleData.rules.find(r=>r.id===c.ruleId));pricing();}},c.path);}};
 form.querySelector('[data-product-template]').onchange=async e=>{uploading++;try{for(const f of e.target.files){if(c.templates.length>=30)throw Error('Use up to 30 templates');const fd=new FormData();fd.set('file',f);const r=await fetch('/api/admin/service-upload',{method:'POST',body:fd}),v=await r.json();if(!r.ok)throw Error(v.error);c.templates.push({label:f.name.replace(/\.pdf$/i,''),url:v.url});templateList();}message('Templates uploaded. Save product to publish.');}catch(err){message(err.message,true);}finally{uploading--;e.target.value='';}};
 form.onsubmit=async e=>{if(e.target!==form)return;e.preventDefault();if(uploading){message('Wait for uploads to finish.',true);return;}e.submitter.disabled=true;try{const fd=new FormData(form);rule.label=String(fd.get('name'));rule.path=String(fd.get('path')).replace(/\/$/,'');const {validateRule}=await import('/studio/model.mjs');validateRule(rule);const saved=await api('admin/rule',{rule,expectedRevision:rule.revision||0});rule.revision=saved.revision;await api('admin/products',{product:{...c,name:fd.get('name'),path:rule.path,description:fd.get('description'),details:fd.get('details'),filePrep:fd.get('filePrep'),reviews:fd.get('reviews'),templateURL:'',templates:c.templates,studioProductId:fd.get('studioProductId'),stock:fd.get('stock')===''?null:Number(fd.get('stock')),active:fd.has('active'),artwork:fd.has('artwork')}});ruleData.rules=(await api('admin/rules')).rules;products=(await api('admin/products')).products;list();$('[data-product-status]').textContent='Product saved and published.';message('Product published.');}catch(err){$('[data-product-status]').textContent=err.message;}finally{e.submitter.disabled=false;}};media();templateList();pricing();}
 root.onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-new-product'))editor();if(b.dataset.editProduct)editor(products.find(p=>p.id===b.dataset.editProduct));};$('[data-stock-filter]').onchange=list;$('[data-search]').oninput=list;list();
}
export async function mountTemplates(root,message){const [{templates},{makes}]=await Promise.all([api('admin/templates'),api('vehicles')]);let rows=templates;root.innerHTML='<div class="toolbar"><button class="primary" data-new-template>Add vector template</button></div><div class="panel" data-list></div><div data-template-editor></div>';const $=s=>root.querySelector(s);
function list(){$('[data-list]').innerHTML=`<h2>Vehicle vector templates</h2><p class="muted">Only published entries with a real vector file and confirmed resale rights appear as available in the shop.</p><div class="scroll"><table><thead><tr><th>Vehicle</th><th>Trim / body</th><th>File</th><th>Published</th><th></th></tr></thead><tbody>${rows.map(t=>`<tr><td>${t.year} ${esc(t.make+' '+t.model)}</td><td>${esc(t.trim+' · '+t.body)}</td><td>${t.fileKey?`<a href="/api/admin/template-file?id=${t.id}">${esc(t.fileName)}</a>`:esc(t.fileName)}</td><td>${t.active?'Yes':'No'}</td><td><button data-edit-template="${t.id}">Edit</button></td></tr>`).join('')}</tbody></table></div>`;}
function editor(row){let current=structuredClone(row||{id:crypto.randomUUID(),make:'Ford',model:'',year:2025,trim:'',body:'',price:25,description:'',fileKey:'',fileName:'',licensed:false,active:false});$('[data-template-editor]').innerHTML=`<form class="panel" data-template-form><h2>Vector template</h2><div class="form-grid"><label>Make<select name="make">${makes.map(m=>`<option value="${m}" ${m===current.make?'selected':''}>${m}</option>`).join('')}</select></label>${[['model','Model','text'],['year','Year','number'],['trim','Trim','text'],['body','Body / configuration','text'],['price','Price (CAD)','number']].map(([k,l,type])=>`<label>${l}<input name="${k}" type="${type}" value="${esc(current[k])}" ${k==='model'?'required':''} ${k==='price'?'min="0" step=".01"':''}></label>`).join('')}<label>Description<textarea name="description">${esc(current.description)}</textarea></label><label>Preview image · optional<input data-preview-upload type="file" accept="image/png,image/jpeg,image/webp"></label><p data-preview-status></p><label>Vector file<input data-vector-upload type="file" accept=".svg,.pdf,.ai,.zip"></label><p data-file-name>${esc(current.fileName)}</p><label class="check"><input name="licensed" type="checkbox" ${current.licensed?'checked':''}>I have the rights to sell this vector file.</label><label class="check"><input name="active" type="checkbox" ${current.active?'checked':''}>Publish in the shop</label></div><button class="primary" style="margin-top:20px">Save template</button><p data-template-status role="status"></p></form>`;$( '[data-preview-upload]'.trim()).onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const fd=new FormData();fd.set('file',file);fd.set('kind','preview');const r=await fetch('/api/admin/template-upload',{method:'POST',body:fd}),v=await r.json();if(!r.ok)throw Error(v.error);current.previewKey=v.key;$('[data-preview-status]').textContent='Preview uploaded.';}catch(err){$('[data-template-status]').textContent=err.message;}};$('[data-vector-upload]').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const fd=new FormData();fd.set('file',file);const r=await fetch('/api/admin/template-upload',{method:'POST',body:fd}),v=await r.json();if(!r.ok)throw Error(v.error);current.fileKey=v.key;current.fileName=v.name;$('[data-file-name]').textContent=v.name;message('Vector file uploaded.');}catch(err){$('[data-template-status]').textContent=err.message;}};$('[data-template-form]').onsubmit=async e=>{e.preventDefault();try{const fd=new FormData(e.target);await api('admin/templates',{template:{...current,...Object.fromEntries(fd),year:Number(fd.get('year')),price:Number(fd.get('price')),licensed:fd.has('licensed'),active:fd.has('active')}});rows=(await api('admin/templates')).templates;list();$('[data-template-editor]').innerHTML='';message('Vector template saved.');}catch(err){$('[data-template-status]').textContent=err.message;}};}
root.onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-new-template'))editor();if(b.dataset.editTemplate)editor(rows.find(t=>t.id===b.dataset.editTemplate));};list();}
